"""
roman_urdu.py — Roman Urdu -> Urdu script transliteration.

Dictionary-first, longest-match-character-cascade fallback: known words
(707 of them, covering pronouns, common verbs in their usual conjugated
forms, etc.) are looked up directly; anything else is transliterated
character-by-character, checking 4-letter clusters first, then 3, then 2,
then 1 — so aspirated consonants like "kh"/"gh"/"bh"/"ph"/"ch" (which are
one Urdu letter, not two) are matched before they get split apart.

This is a best-effort phonetic convenience, not a guarantee of correct
canonical spelling — Urdu retains a lot of Arabic/Persian etymological
spelling that plain phonetics can't recover (e.g. multiple Roman "s"
sounds map to different Urdu letters depending on word origin). For a
word this doesn't get right, just type it directly in Urdu script instead.

Ported from the MIT-licensed romanUrdu2UrduTranslitration project by
Hamza Afzal (https://github.com/spyhunk/romanUrdu2UrduTranslitration) —
same dictionary and matching algorithm, translated from JS to Python.
"""

