# ======================================================================
# Phonetic fallback engine (v2) -- used only when a word (and its
# normalized spelling, and its closest fuzzy dictionary match) are not
# found in COMMON_WORDS above. Reconstructs Urdu script letter-by-letter
# from the Roman spelling: vowel runs (short/long, word-initial/medial/
# final forms all differ in Urdu orthography), aspirated/retroflex
# consonant digraphs, context-sensitive kh/gh (خ vs کھ, غ vs گھ), ~35
# verb/plural/future suffix patterns, and the vowel-before-h elision
# that makes "pehle", "shehar", "bahut" etc. read correctly. Tuned
# against several thousand everyday Roman-Urdu spellings; still a
# best-effort guess for words that are not in the dictionary above,
# since several Urdu letter pairs (ه/ح, س/ص, ز/ض/ظ/ذ, ت/ط) sound
# identical in Roman spelling but are not interchangeable in the script.
# ======================================================================
VOWELS = "aeiou"

# ---------------------------------------------------------------- consonants
